-- No schema installation, role changes, maintenance locks or feature activation.
begin transaction isolation level repeatable read read only;
set local statement_timeout='20s';set local lock_timeout='2s';
select jsonb_build_object('observedAt',clock_timestamp(),'readOnly',current_setting('transaction_read_only'),
'counts',jsonb_build_object('trips',(select count(*) from public.trips),'users',(select count(*) from auth.users),'members',(select count(*) from public.trip_members),'itineraryItems',(select count(*) from public.itinerary_items),'budgets',(select count(*) from public.budget_items),'budgetParticipants',(select count(*) from public.budget_item_participants),'actuals',(select count(*) from public.actual_expenses),'actualParticipants',(select count(*) from public.actual_expense_participants),'baselines',(select count(*) from public.trip_budget_baselines),'attachments',(select count(*) from public.attachments),'storageObjects',(select count(*) from storage.objects)),
'financial',jsonb_build_object('foreignBudgets',(select count(*) from public.budget_items where currency<>'TWD'),'retainedBudgetIdentities',(select count(*) from public.budget_items b where exists(select 1 from public.actual_expenses a where a.budget_item_id=b.id or a.budget_origin_id=b.id)),'activePayments',(select count(*) from public.actual_expenses where payment_active),'inactivePayments',(select count(*) from public.actual_expenses where not payment_active),'paymentHistoryEntries',(select coalesce(sum(jsonb_array_length(payment_history)),0) from public.actual_expenses),'originRows',(select count(*) from public.actual_expenses where budget_origin_id is not null),'sourceKinds',(select jsonb_object_agg(k,n) from (select coalesce(payment_origin,'NULL') k,count(*) n from public.actual_expenses group by payment_origin) v),'frozenBaselines',(select count(*) from public.trip_budget_baselines where departure_at<=clock_timestamp()),'futureBaselines',(select count(*) from public.trip_budget_baselines where departure_at>clock_timestamp()),'receiptAttachments',(select count(*) from public.attachments where target_type='actual_expense'),'receiptMetadataWithoutObject',(select count(*) from public.attachments a where target_type='actual_expense' and not exists(select 1 from storage.objects o where o.bucket_id='trip-attachments' and o.name=a.file_url)),'orphanBudgetParticipants',(select count(*) from public.budget_item_participants p where not exists(select 1 from public.budget_items b where b.id=p.budget_item_id)),'orphanActualParticipants',(select count(*) from public.actual_expense_participants p where not exists(select 1 from public.actual_expenses a where a.id=p.actual_expense_id))),
'fingerprints',jsonb_build_object(
'budgets',(select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) order by id),'[]')::text,'UTF8')),'hex') from public.budget_items t),
'budgetParticipants',(select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) order by id),'[]')::text,'UTF8')),'hex') from public.budget_item_participants t),
'actuals',(select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) order by id),'[]')::text,'UTF8')),'hex') from public.actual_expenses t),
'actualParticipants',(select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) order by id),'[]')::text,'UTF8')),'hex') from public.actual_expense_participants t),
'baselines',(select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) order by trip_id),'[]')::text,'UTF8')),'hex') from public.trip_budget_baselines t),
'attachments',(select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) order by id),'[]')::text,'UTF8')),'hex') from public.attachments t),
'storageMetadata',(select encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) order by id),'[]')::text,'UTF8')),'hex') from storage.objects t),
'tripRates',(select encode(sha256(convert_to(coalesce(jsonb_agg(jsonb_build_object('id',id,'rates',budget_exchange_rates) order by id),'[]')::text,'UTF8')),'hex') from public.trips)),
'protocolRelations',(select jsonb_object_agg(name,to_regclass('app_private.'||name) is not null) from unnest(array['budget_metadata_protocol','budget_finance_protocol','budget_payment_protocol','budget_source_protocol','budget_receipt_protocol','budget_lifecycle_protocol','budget_metadata_undo_protocol'])name),
'leases',jsonb_build_object('stored',(select count(*) from app_private.budget_edit_leases),'active',(select count(*) from app_private.budget_edit_leases where expires_at>clock_timestamp()),'oldestActiveExpiry',(select min(expires_at) from app_private.budget_edit_leases where expires_at>clock_timestamp())),
'storageBuckets',(select jsonb_agg(jsonb_build_object('id',id,'private',not public,'limit',file_size_limit,'mime',allowed_mime_types) order by id) from storage.buckets),
'transactions',(select jsonb_agg(jsonb_build_object('state',state,'application',application_name,'ageSeconds',extract(epoch from clock_timestamp()-xact_start)::int,'waitType',wait_event_type,'waitEvent',wait_event,'blocked',pg_blocking_pids(pid)<>'{}'::int[],'readQueryCandidate',query~* '^\s*(select|show|begin.*read only)') order by xact_start) from pg_stat_activity where pid<>pg_backend_pid() and backend_type='client backend' and xact_start is not null),
'health',jsonb_build_object('databaseBytes',pg_database_size(current_database()),'stats',(select jsonb_build_object('backends',numbackends,'commits',xact_commit,'rollbacks',xact_rollback,'deadlocks',deadlocks,'tempFiles',temp_files,'tempBytes',temp_bytes,'statsReset',stats_reset) from pg_stat_database where datname=current_database()),'invalidIndexes',(select count(*) from pg_index where not indisvalid),'unvalidatedConstraints',(select count(*) from pg_constraint where not convalidated),'idleInTransaction',(select count(*) from pg_stat_activity where state='idle in transaction'),'waitingClientLocks',(select count(*) from pg_stat_activity where backend_type='client backend' and wait_event_type='Lock'))
) inventory;
commit;
